/**
 * Derives every web icon + share image from the AppLogos/ pack.
 *
 * AppLogos/ is the shipped source of truth (generated by appicon.co for the
 * native apps). Nothing in it is web-shaped, so this script cuts the pieces the
 * browser and the crawlers actually want:
 *
 *   appstore.png                  — 1024 mark on a transparent surround. Every
 *                                   raster below derives from it, flattened
 *                                   onto white: the launcher and home-screen
 *                                   surfaces draw their own plate and composite
 *                                   alpha onto black, so they want an opaque
 *                                   tile, and white is the manifest's
 *                                   background_color.
 *   android/adaptive-foreground   — 1024 with the mark inset in the safe area,
 *                                   which is exactly the maskable contract.
 *
 * The pack's own vector (AppIcon.icon/Assets/icon.png — an SVG despite the
 * extension) is deliberately NOT the mark source. It is an autotrace: three
 * dozen stacked translucent paths reproducing the raster's antialiasing, with
 * the face knocked out as holes rather than drawn. Inline in the navbar that
 * would be ~56 KB of markup whose face turns whatever colour it sits on. So
 * geometry comes from wimall-mark.svg beside this file — a clean two-group
 * trace of the same mark, verified pixel-faithful to the pack — while the
 * colour is sampled from the pack itself, so a recoloured pack still flows
 * through without touching the geometry.
 *
 * Run: npm run gen:app-icons
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import sharp from "sharp";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, "..");
const SRC = path.join(ROOT, "AppLogos");
const P = (...p) => path.join(ROOT, ...p);

/** 1024 mark on transparent — the colour reference and every raster's source. */
const TILE_SRC = path.join(SRC, "appstore.png");

/** Site dark canvas + brand green, mirrored from globals.css / tailwind.config. */
const INK = "#14130F";
const GREEN = "#068554";
const GREEN_LIGHT = "#22BD82";

/**
 * The mark's body colour, read off the pack rather than hardcoded — this is the
 * one thing that changes when the brand is recoloured. Takes the most common
 * fully-opaque non-white pixel: the bag body dominates the artwork, and the
 * face details are the only white.
 */
async function sampleBrandColour() {
  const { data, info } = await sharp(TILE_SRC).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  const tally = new Map();
  for (let i = 0; i < data.length; i += info.channels) {
    const [r, g, b, a] = [data[i], data[i + 1], data[i + 2], data[i + 3]];
    if (a < 250) continue; // antialiased edge, not a flat fill
    if (r > 240 && g > 240 && b > 240) continue; // the white face
    const key = (r << 16) | (g << 8) | b;
    tally.set(key, (tally.get(key) ?? 0) + 1);
  }
  const [top] = [...tally.entries()].sort((a, b) => b[1] - a[1]);
  if (!top) throw new Error("AppLogos/appstore.png: no opaque body pixels — did the pack change?");
  return "#" + top[0].toString(16).padStart(6, "0").toUpperCase();
}

const BRAND = await sampleBrandColour();

const written = [];
async function emit(rel, buf) {
  const abs = P(rel);
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  fs.writeFileSync(abs, buf);
  written.push(`${rel}  (${(buf.length / 1024).toFixed(1)} KB)`);
}

// ── The mark, as a transparent vector ───────────────────────────────────────

const source = fs.readFileSync(path.join(HERE, "wimall-mark.svg"), "utf8");

function group(fill) {
  const m = source.match(new RegExp(`<g fill="${fill}">([\\s\\S]*?)</g>`));
  if (!m) throw new Error(`wimall-mark.svg: ${fill} group not found — did the trace change?`);
  const paths = m[1].match(/<path\b[^>]*\/>/g);
  if (!paths?.length) throw new Error(`wimall-mark.svg: ${fill} group has no paths`);
  return paths;
}

const bodyPaths = group("#f19409").join("");
// Skip the first white path: it is the backdrop the tile is cut out of, and
// keeping it would reintroduce the opaque square. The rest are the face.
const detailPaths = group("#fffffe").slice(1).join("");

/**
 * Body in the pack's brand colour, white face on top, nothing behind either —
 * so the mark reads the same on the light navbar, the dark navbar and the auth
 * panes without a plate to sit on. (The trace's own #f19409 / #fffffe are just
 * the group labels this script splits on; neither survives into the output.)
 */
const markBody = `<g fill="${BRAND}">${bodyPaths}</g><g fill="#FFFFFF">${detailPaths}</g>`;

const markSvg = (viewBox, size) =>
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}" width="${size}" height="${size}">${markBody}</svg>`;

// The artwork sits on a 500-unit canvas with generous native-icon padding. For
// a 24px navbar logo that padding is dead weight, so measure the real bounds
// once and bake a tight viewBox into the emitted file.
const PROBE = 2000;
const probe = await sharp(Buffer.from(markSvg("0 0 500 500", PROBE)))
  .png()
  .trim({ threshold: 1 })
  .toBuffer({ resolveWithObject: true });
const k = 500 / PROBE;
const box = {
  x: -probe.info.trimOffsetLeft * k,
  y: -probe.info.trimOffsetTop * k,
  w: probe.info.width * k,
  h: probe.info.height * k,
};
// Square it up so the mark never distorts, then breathe 2% so strokes at the
// edge don't touch the box.
const side = Math.max(box.w, box.h) * 1.04;
const vb = [
  +(box.x + box.w / 2 - side / 2).toFixed(2),
  +(box.y + box.h / 2 - side / 2).toFixed(2),
  +side.toFixed(2),
  +side.toFixed(2),
].join(" ");

const MARK_SVG =
  `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${vb}" role="img">` +
  `<title>WiMall</title>${markBody}</svg>\n`;
// The mark ships in two forms and no third: src/app/icon.svg below is the
// standalone file (served at /icon.svg for anything that needs a URL), and this
// component is what the UI renders. The mark sits in the navbar above the fold,
// where an <img> would pop in a frame late on a cold cache.
const jsx = (paths, fill) =>
  paths
    .match(/<path\b[^>]*\/>/g)
    .map((p) => `      ${p.replace(/^<path /, `<path fill="${fill}" `)}`)
    .join("\n");

await emit(
  "src/components/brand/WiMallMark.generated.tsx",
  Buffer.from(`// ─────────────────────────────────────────────────────────────────────────────
// GENERATED FILE — do not edit by hand.
//
// The WiMall bag mark, in the brand colour sampled from AppLogos/. Solid body,
// white face, and a transparent surround, so it sits on the light navbar, the
// dark navbar and the auth panes without a plate behind it.
//
// Sizing is the caller's: the viewBox is trimmed to the artwork, so the mark
// fills whatever box it is given. Pass w-*/h-* (or width/height) — never both a
// size and a wrapper that crops it.
//
// Regenerate with: npm run gen:app-icons
// ─────────────────────────────────────────────────────────────────────────────
import type { SVGProps } from "react";

interface WiMallMarkProps extends SVGProps<SVGSVGElement> {
  /** Accessible name. Omit when the mark sits inside an already-labelled link. */
  title?: string;
}

export default function WiMallMark({ title, ...props }: WiMallMarkProps) {
  return (
    <svg
      viewBox="${vb}"
      role="img"
      aria-hidden={title ? undefined : true}
      xmlns="http://www.w3.org/2000/svg"
      {...props}
    >
      {title ? <title>{title}</title> : null}
${jsx(bodyPaths, BRAND)}
${jsx(detailPaths, "#FFFFFF")}
    </svg>
  );
}
`),
);

/**
 * Raster the mark at a given px size, transparent background. Rendered large
 * and scaled down: the traced source has no antialiasing of its own, so at
 * favicon sizes a direct render comes out ragged.
 */
const rasterMark = (size) =>
  sharp(Buffer.from(markSvg(vb, Math.max(size * 4, 512))))
    .resize(size, size, { kernel: "lanczos3" })
    .png()
    .toBuffer();

// ── Favicons ────────────────────────────────────────────────────────────────

// Modern browsers take the SVG; it stays crisp and needs no size negotiation.
await emit("src/app/icon.svg", Buffer.from(MARK_SVG));

/** Minimal PNG-in-ICO container (ICONDIR + ICONDIRENTRY[] + payloads). */
function encodeIco(images) {
  const header = Buffer.alloc(6);
  header.writeUInt16LE(0, 0); // reserved
  header.writeUInt16LE(1, 2); // type: icon
  header.writeUInt16LE(images.length, 4);

  const dir = Buffer.alloc(16 * images.length);
  let offset = header.length + dir.length;
  for (const [i, img] of images.entries()) {
    const e = i * 16;
    dir.writeUInt8(img.size >= 256 ? 0 : img.size, e); // 0 encodes 256
    dir.writeUInt8(img.size >= 256 ? 0 : img.size, e + 1);
    dir.writeUInt8(0, e + 2); // palette size
    dir.writeUInt8(0, e + 3); // reserved
    dir.writeUInt16LE(1, e + 4); // colour planes
    dir.writeUInt16LE(32, e + 6); // bits per pixel
    dir.writeUInt32LE(img.data.length, e + 8);
    dir.writeUInt32LE(offset, e + 12);
    offset += img.data.length;
  }
  return Buffer.concat([header, dir, ...images.map((i) => i.data)]);
}

const icoSizes = [16, 32, 48];
const icoImages = await Promise.all(
  icoSizes.map(async (size) => ({ size, data: await rasterMark(size) })),
);
await emit("src/app/favicon.ico", encodeIco(icoImages));

// ── Home-screen + PWA icons ─────────────────────────────────────────────────

/**
 * The opaque tile. The pack ships the mark on transparency, and these surfaces
 * cannot take alpha — iOS composites the home-screen icon onto black, and an
 * installed launcher draws its own plate — so flatten onto the manifest's
 * background_color first. Rendered once and reused by every size below.
 */
const tile = await sharp(TILE_SRC).flatten({ background: "#FFFFFF" }).png().toBuffer();

await emit("src/app/apple-icon.png", await sharp(tile).resize(180, 180).png().toBuffer());

for (const size of [192, 512]) {
  await emit(`public/icons/icon-${size}.png`, await sharp(tile).resize(size, size).png().toBuffer());
}

// Maskable: full bleed, mark inside the centre safe zone. The adaptive
// foreground already has that inset — it only needs its transparent margin
// filled so Android's mask has something to bite into.
await emit(
  "public/icons/maskable-512.png",
  await sharp(path.join(SRC, "android/adaptive-foreground.png"))
    .flatten({ background: "#FFFFFF" })
    .resize(512, 512)
    .png()
    .toBuffer(),
);

// ── Share card ──────────────────────────────────────────────────────────────

const OG_W = 1200;
const OG_H = 630;
const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
// Plus Jakarta Sans is the site face but is web-loaded, not installed; the
// fallbacks are what actually render here.
const FONT = "Plus Jakarta Sans, Segoe UI Variable Display, Segoe UI, Inter, Arial, sans-serif";

const TILE = 132;
const PAD = 88;
const tilePng = await sharp(tile).resize(TILE, TILE).png().toBuffer();

const ogBackdrop = `<svg xmlns="http://www.w3.org/2000/svg" width="${OG_W}" height="${OG_H}">
  <defs>
    <radialGradient id="glow" cx="0.18" cy="0.12" r="0.9">
      <stop offset="0" stop-color="${GREEN_LIGHT}" stop-opacity="0.30"/>
      <stop offset="0.55" stop-color="${GREEN}" stop-opacity="0.08"/>
      <stop offset="1" stop-color="${INK}" stop-opacity="0"/>
    </radialGradient>
    <radialGradient id="lift" cx="0.92" cy="0.9" r="0.7">
      <stop offset="0" stop-color="${GREEN}" stop-opacity="0.20"/>
      <stop offset="1" stop-color="${INK}" stop-opacity="0"/>
    </radialGradient>
    <linearGradient id="rule" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0" stop-color="${GREEN_LIGHT}"/>
      <stop offset="0.55" stop-color="${GREEN}"/>
      <stop offset="1" stop-color="${GREEN_LIGHT}"/>
    </linearGradient>
    <clipPath id="squircle">
      <rect x="${PAD}" y="${PAD}" width="${TILE}" height="${TILE}" rx="30" ry="30"/>
    </clipPath>
  </defs>
  <rect width="${OG_W}" height="${OG_H}" fill="${INK}"/>
  <rect width="${OG_W}" height="${OG_H}" fill="url(#glow)"/>
  <rect width="${OG_W}" height="${OG_H}" fill="url(#lift)"/>
  <rect x="0" y="${OG_H - 10}" width="${OG_W}" height="10" fill="url(#rule)"/>
</svg>`;

const ogText = `<svg xmlns="http://www.w3.org/2000/svg" width="${OG_W}" height="${OG_H}">
  <text x="${PAD + TILE + 32}" y="${PAD + 90}" font-family="${FONT}" font-size="76" font-weight="800"
        letter-spacing="-2.5" fill="#FFFFFF">WiMall</text>
  <text x="${PAD}" y="${PAD + 268}" font-family="${FONT}" font-size="62" font-weight="800"
        letter-spacing="-1.8" fill="#FFFFFF">${esc("Commerce runs on conversation.")}</text>
  <text x="${PAD}" y="${PAD + 336}" font-family="${FONT}" font-size="31" font-weight="500"
        fill="#B9B3A7">${esc("AI-powered ecommerce for WhatsApp-first businesses.")}</text>
  <text x="${PAD}" y="${PAD + 430}" font-family="${FONT}" font-size="26" font-weight="600"
        letter-spacing="3" fill="${GREEN_LIGHT}">${esc("VENDORS · AGENCIES · AGENTS")}</text>
</svg>`;

const ogCard = await sharp(Buffer.from(ogBackdrop))
  .composite([
    { input: await roundedTile(tilePng, TILE, 30), left: PAD, top: PAD },
    { input: Buffer.from(ogText), left: 0, top: 0 },
  ])
  .png()
  .toBuffer();

/** Round the app tile's corners so it reads as an icon, not a photo. */
async function roundedTile(png, size, radius) {
  const mask = Buffer.from(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}">` +
      `<rect width="${size}" height="${size}" rx="${radius}" ry="${radius}" fill="#fff"/></svg>`,
  );
  return sharp(png)
    .composite([{ input: mask, blend: "dest-in" }])
    .png()
    .toBuffer();
}

await emit("src/app/opengraph-image.png", ogCard);
await emit("src/app/twitter-image.png", ogCard);

console.log(`Generated from AppLogos/ (brand ${BRAND}):`);
for (const w of written) console.log("  " + w);
